package fr.fkamis;

import com.google.gson.JsonParser;
import org.bukkit.configuration.file.YamlConfiguration;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class VNextTest {
    private Map<String,Number> settings(){return new HashMap<>(GameSettings.DEFAULTS);}
    private MatchStatistics stats(){var model=new MatchStatistics();model.member(new UUID(0,1),"Alice","Rouge");model.member(new UUID(0,2),"Bob","Bleue");return model;}
    @Test void validateDefaultsAndEveryTeamFormat(){for(int size=1;size<=4;size++){int capacity=size;var values=settings();values.put("players-per-team",size);assertDoesNotThrow(()->GameSettings.validate(values,List.of(capacity,capacity,capacity,capacity)));}}
    @Test void rejectIncoherentDaysAndImpossibleRadius(){for(String key:List.of("pvp-day","nether-day")){var values=settings();values.put(key,4);assertThrows(IllegalArgumentException.class,()->GameSettings.validate(values,List.of(2,2,2,2)));}var values=settings();values.put("capture-radius",1);assertThrows(IllegalArgumentException.class,()->GameSettings.validate(values,List.of(2,2,2,2)));}
    @Test void rejectFractionalIntegerAndNonFiniteNumbers(){for(String value:List.of("NaN","Infinity","1.5","-1","texte"))assertThrows(IllegalArgumentException.class,()->GameSettings.parse("players-per-team",value));assertThrows(IllegalArgumentException.class,()->GameSettings.parse("capture-radius","NaN"));}
    @Test void doNotDecreaseCapacityUnderSavedRoster(){var values=settings();values.put("players-per-team",1);assertThrows(IllegalArgumentException.class,()->GameSettings.validate(values,List.of(2,2,2,2)));}
    @Test void splitActivePauseAndOfflineTime(){var model=stats();model.startedAt=1000;model.elapsed(5000,true,List.of(new UUID(0,1)));model.elapsed(3000,false,List.of(new UUID(0,1)));assertEquals(5000,model.activeMillis);assertEquals(3000,model.pausedMillis);assertEquals(5000,model.players.get(new UUID(0,1)).activeMillis);assertEquals(0,model.players.get(new UUID(0,2)).activeMillis);assertEquals(19000,model.totalMillis(20000));}
    @Test void deathIsIdempotentUntilRespawnAndNaturalDeathsAreNotKills(){var model=stats();UUID red=new UUID(0,1),blue=new UUID(0,2);assertTrue(model.death(blue,red));assertFalse(model.death(blue,red));assertEquals(1,model.players.get(red).kills);model.respawn(blue);assertTrue(model.death(blue,null));assertEquals(2,model.players.get(blue).deaths);assertEquals(1,model.players.get(blue).pvpDeaths);assertEquals(1,model.players.get(red).kills);}
    @Test void selfAndFriendlyDamageCannotBecomePvpStats(){var model=stats();UUID red=new UUID(0,1);model.member(new UUID(0,3),"Ami","Rouge");model.damage(red,red,8);model.damage(red,new UUID(0,3),8);model.damage(red,new UUID(0,2),Double.NaN);assertEquals(0,model.players.get(red).dealt);}
    @Test void captureCreditAndTeamTotalsAreNotDuplicated(){var model=stats();UUID red=new UUID(0,1);model.captureEvent("Rouge","Bleue",List.of(red,red,new UUID(0,2)));model.captureEvent("Rouge","Bleue",List.of(red));assertEquals(1,model.players.get(red).captures);assertEquals(0,model.players.get(new UUID(0,2)).captures);assertEquals(1,model.team("Rouge").captures());}
    @Test void statisticsRoundTripPreservesUnknownFieldsAndRejectsFutureSchema(){var model=stats();model.damage(new UUID(0,1),new UUID(0,2),3.5);var raw=JsonParser.parseString(model.json()).getAsJsonObject();raw.addProperty("future-note","conserver");var restored=MatchStatistics.read(raw.toString());assertEquals(3.5,restored.players.get(new UUID(0,1)).dealt);assertEquals("conserver",JsonParser.parseString(restored.json()).getAsJsonObject().get("future-note").getAsString());raw.addProperty("schema",2);assertThrows(IllegalArgumentException.class,()->MatchStatistics.read(raw.toString()));}
    @Test void removedPregameMemberDoesNotReappearFromPreservedJson(){var restored=MatchStatistics.read(stats().json());restored.players.remove(new UUID(0,2));assertFalse(MatchStatistics.read(restored.json()).players.containsKey(new UUID(0,2)));}
    @Test void resetTokensExpireAndDetectChangedState(){var plan=ResetPlan.create("état",1000);assertDoesNotThrow(()->plan.verify(plan.token(),"état",2000));assertThrows(IllegalArgumentException.class,()->plan.verify("faux","état",2000));assertThrows(IllegalArgumentException.class,()->plan.verify(plan.token(),"autre",2000));assertThrows(IllegalArgumentException.class,()->plan.verify(plan.token(),"état",301000));}
    @Test void logicalResetKeepsUnknownDataTerritoriesSpawnsAndSpentSupplies(){var state=new YamlConfiguration();state.set("schema",1);state.set("custom-note.keep",42);state.set("native.TeamManager.Rouge.Members",List.of("Alice"));state.set("native.TeamManager.Rouge.Base.Radius",80);state.set("spawns.Rouge.x",240);state.set("objectives.Rouge.x",12);state.set("roster.ancien.name","Alice");state.set("supplies.event",9);state.set("supplies.drops.spent.status","CLAIMED");state.set("supplies.drops.open.status","ACTIVE");state.set("supplies.drops.open.items",List.of("objet"));var reset=ResetService.logicalCandidate(state,List.of("Rouge","Bleue","Verte","Jaune"),1800,2);assertFalse(reset.getBoolean("started"));assertFalse(reset.contains("roster"));assertFalse(reset.contains("objectives"));assertEquals(42,reset.getInt("custom-note.keep"));assertEquals(80,reset.getInt("native.TeamManager.Rouge.Base.Radius"));assertEquals(240,reset.getInt("spawns.Rouge.x"));assertTrue(reset.getStringList("native.TeamManager.Rouge.Members").isEmpty());assertEquals(9,reset.getInt("supplies.event"));assertEquals("CLAIMED",reset.getString("supplies.drops.spent.status"));assertEquals("EXPIRED",reset.getString("supplies.drops.open.status"));assertTrue(reset.getList("supplies.drops.open.items").isEmpty());assertTrue(state.contains("roster"));}
    @Test void protectionBoxHasExactVerticalAndHorizontalEdges(){var box=new ProtectedPlaces.Box("spawn","world",-3,60,-3,3,66,3);assertTrue(box.contains(3,66,-3));assertFalse(box.contains(4,66,-3));assertFalse(box.contains(0,59,0));}
    @Test void settingsTransactionKeepsUnknownTextAndValidatesProvenance()throws Exception {
        Path folder=Path.of("../../.cache/test-temp/vnext-settings-"+UUID.randomUUID()).normalize();Files.createDirectories(folder);
        Files.writeString(folder.resolve("config.yml"),"unknown: conserver\nplayers-per-team: 2\n");Files.writeString(folder.resolve("supplies.yml"),"interval-seconds: 1800\n");
        SettingsTransaction.commit(folder,Map.of("config.yml","unknown: conserver\nplayers-per-team: 3\n","supplies.yml","interval-seconds: 1200\n"));
        assertTrue(Files.readString(folder.resolve("config.yml")).contains("unknown: conserver"));assertFalse(Files.exists(folder.resolve("settings-transaction.json")));
        assertThrows(IllegalArgumentException.class,()->SettingsTransaction.commit(folder,Map.of("state.yml","interdit")));
    }
}
